#!/usr/bin/env python3
"""Build a transparent OSM accessibility baseline for Rooted Jing-Zhang.

This is an evidence baseline, not a displacement prediction. It deliberately
does not infer rent, tenure, income, resident identity, or business survival.
"""

from __future__ import annotations

import argparse
import json
from datetime import datetime, timezone
from pathlib import Path

import networkx as nx
import osmnx as ox
from shapely.geometry import Point, mapping, shape


SUBMISSION = Path(__file__).resolve().parents[1]
ANALYSIS = Path(__file__).resolve().parent
BOUNDARY = SUBMISSION / "geometry/site_boundary.geojson"
CATEGORIES = (
    "public_transport",
    "daily_food",
    "health",
    "care_education",
    "public_basics",
)
THRESHOLDS_M = (800, 1200)


def write_json(path: Path, payload: object) -> None:
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def clean(value):
    if value is None:
        return None
    try:
        if value != value:
            return None
    except TypeError:
        pass
    if isinstance(value, (list, tuple, set)):
        return [clean(v) for v in value]
    return str(value)


def feature_categories(row) -> list[str]:
    amenity = clean(row.get("amenity"))
    shop = clean(row.get("shop"))
    railway = clean(row.get("railway"))
    public_transport = clean(row.get("public_transport"))

    categories: list[str] = []
    if public_transport in {"platform", "station", "stop_position"} or railway in {
        "station",
        "subway_entrance",
        "platform",
        "stop",
    }:
        categories.append("public_transport")
    if shop in {"supermarket", "convenience", "bakery", "greengrocer"} or amenity in {
        "marketplace",
        "food_court",
    }:
        categories.append("daily_food")
    if amenity in {"clinic", "doctors", "hospital", "pharmacy", "dentist"}:
        categories.append("health")
    if amenity in {
        "kindergarten",
        "school",
        "childcare",
        "social_facility",
        "community_centre",
    }:
        categories.append("care_education")
    if amenity in {
        "toilets",
        "drinking_water",
        "library",
        "community_centre",
        "post_office",
        "shelter",
    }:
        categories.append("public_basics")
    return categories


def representative_point(geom):
    if geom is None or geom.is_empty:
        return None
    if isinstance(geom, Point):
        return geom
    return geom.representative_point()


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--cache", default=str(ANALYSIS / ".osmnx-cache"))
    args = parser.parse_args()

    boundary_data = json.loads(BOUNDARY.read_text(encoding="utf-8"))
    site = shape(boundary_data["features"][0]["geometry"])
    ox.settings.use_cache = True
    ox.settings.cache_folder = args.cache
    ox.settings.requests_timeout = 240

    graph = ox.graph.graph_from_polygon(
        site,
        network_type="walk",
        simplify=True,
        retain_all=True,
    )
    tags = {
        "amenity": True,
        "shop": True,
        "public_transport": True,
        "railway": ["station", "subway_entrance", "platform", "stop"],
    }
    raw = ox.features.features_from_polygon(site, tags)

    facility_features = []
    facility_nodes: dict[str, set[int]] = {category: set() for category in CATEGORIES}
    local_shop_candidates = 0
    for index, row in raw.iterrows():
        categories = feature_categories(row)
        shop = clean(row.get("shop"))
        if shop:
            local_shop_candidates += 1
        if not categories and not shop:
            continue
        point = representative_point(row.geometry)
        if point is None:
            continue
        nearest = int(ox.distance.nearest_nodes(graph, point.x, point.y))
        for category in categories:
            facility_nodes[category].add(nearest)
        element_type, osmid = index if isinstance(index, tuple) else ("unknown", index)
        facility_features.append(
            {
                "type": "Feature",
                "id": f"osm-{element_type}-{osmid}",
                "properties": {
                    "osm_element_type": clean(element_type),
                    "osm_id": clean(osmid),
                    "name": clean(row.get("name")),
                    "amenity": clean(row.get("amenity")),
                    "shop": shop,
                    "public_transport": clean(row.get("public_transport")),
                    "railway": clean(row.get("railway")),
                    "access_categories": categories,
                    "nearest_walk_node": nearest,
                    "source": "OpenStreetMap",
                    "license": "ODbL-1.0",
                },
                "geometry": mapping(point),
            }
        )

    undirected = ox.convert.to_undirected(graph)
    distances: dict[str, dict[int, float]] = {}
    for category, sources in facility_nodes.items():
        distances[category] = (
            nx.multi_source_dijkstra_path_length(undirected, sources, weight="length") if sources else {}
        )

    access_features = []
    coverage = {
        str(threshold): {category: 0 for category in CATEGORIES} for threshold in THRESHOLDS_M
    }
    all_access_1200 = 0
    nodes = list(graph.nodes(data=True))
    for node_id, attrs in nodes:
        nearest_by_category = {
            category: round(float(distances[category].get(node_id, float("inf"))), 1)
            for category in CATEGORIES
        }
        for category, distance in nearest_by_category.items():
            for threshold in THRESHOLDS_M:
                if distance <= threshold:
                    coverage[str(threshold)][category] += 1
        within_1200 = sum(distance <= 1200 for distance in nearest_by_category.values())
        if within_1200 == len(CATEGORIES):
            all_access_1200 += 1
        access_features.append(
            {
                "type": "Feature",
                "id": f"walk-node-{node_id}",
                "properties": {
                    "node_id": int(node_id),
                    "nearest_m": {
                        category: (None if distance == float("inf") else distance)
                        for category, distance in nearest_by_category.items()
                    },
                    "categories_within_1200m": within_1200,
                    "source": "OpenStreetMap walk network and tags",
                    "interpretation_limit": "OSM tag coverage only; absence is not proof of no facility",
                },
                "geometry": mapping(Point(float(attrs["x"]), float(attrs["y"]))),
            }
        )

    node_count = len(nodes)
    for threshold in THRESHOLDS_M:
        for category in CATEGORIES:
            count = coverage[str(threshold)][category]
            coverage[str(threshold)][category] = {
                "node_count": count,
                "share_of_walk_nodes": round(count / node_count, 6) if node_count else None,
            }

    generated_at = datetime.now(timezone.utc).replace(microsecond=0).isoformat()
    baseline = {
        "schema_version": "1.0.0",
        "generated_at": generated_at,
        "analysis_name": "Rooted Jing-Zhang OSM walking and daily-service baseline",
        "boundary_role": "provisional_constraint",
        "crs": "EPSG:4326 / WGS84",
        "source": {
            "name": "OpenStreetMap",
            "attribution": "© OpenStreetMap contributors",
            "license": "ODbL-1.0",
            "query_tags": tags,
        },
        "network": {
            "walk_nodes": graph.number_of_nodes(),
            "walk_edges_directed": graph.number_of_edges(),
        },
        "facilities": {
            "raw_tagged_objects": len(raw),
            "selected_objects": len(facility_features),
            "local_shop_candidates": local_shop_candidates,
            "category_source_node_counts": {
                category: len(nodes_) for category, nodes_ in facility_nodes.items()
            },
        },
        "walk_access_coverage": coverage,
        "all_five_categories_within_1200m": {
            "node_count": all_access_1200,
            "share_of_walk_nodes": round(all_access_1200 / node_count, 6) if node_count else None,
        },
        "limits": [
            "OSM tag coverage is incomplete and uneven; missing tags do not prove missing services.",
            "Facilities are represented by a point and not weighted by capacity, opening hours, price, or quality.",
            "No rent, tenure, income, resident, contract, or business-survival data is used or inferred.",
            "The boundary is provisional and must be replaced and recalculated when official geometry is available.",
        ],
    }
    write_json(ANALYSIS / "osm-baseline.json", baseline)
    write_json(
        ANALYSIS / "osm-facilities.geojson",
        {
            "type": "FeatureCollection",
            "name": "rooted_jingzhang_osm_facilities",
            "license": "ODbL-1.0",
            "attribution": "© OpenStreetMap contributors",
            "features": facility_features,
        },
    )
    write_json(
        ANALYSIS / "osm-access-nodes.geojson",
        {
            "type": "FeatureCollection",
            "name": "rooted_jingzhang_osm_access_nodes",
            "license": "ODbL-1.0",
            "attribution": "© OpenStreetMap contributors",
            "features": access_features,
        },
    )
    print(json.dumps(baseline, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
